fn policy_is_shared(policy: *mut cpufreq_policy) -> bool {
cpumask_nth(1u32, (unsafe { (*policy).cpus.as_mut_ptr() as *mut cpumask }) as *const cpumask) < unsafe { nr_cpu_ids }
}

// lowest frequency at or above target
// highest frequency below or at target
// closest frequency to target
// relation flags
// Get if possible an efficient frequency
// Set by drivers that need to update internal upper and lower boundaries along
// with the target frequency and so the core and governors should also invoke
// the driver if the target frequency does not change, but the policy min or max
// may have changed.
// Set by drivers that want the core to automatically register the cpufreq
// driver as a thermal cooling device.
#[repr(C)]
#[derive(Clone, Copy)]
struct cpufreq_governor {
    name: [u8; 16],
    init: Option<unsafe extern "C" fn(*mut cpufreq_policy) -> i32>,
    exit: Option<unsafe extern "C" fn(*mut cpufreq_policy)>,
    start: Option<unsafe extern "C" fn(*mut cpufreq_policy) -> i32>,
    stop: Option<unsafe extern "C" fn(*mut cpufreq_policy)>,
    limits: Option<unsafe extern "C" fn(*mut cpufreq_policy)>,
    show_setspeed: Option<unsafe extern "C" fn(*mut cpufreq_policy, *mut u8) -> i64>,
    store_setspeed: Option<unsafe extern "C" fn(*mut cpufreq_policy, u32) -> i32>,
    governor_list: list_head,
    owner: *mut module,
    flags: u8,
}


// For governors which change frequency dynamically by themselves
fn cpufreq_policy_apply_limits(policy: *mut cpufreq_policy) {
if (unsafe { (*policy).max }) < unsafe { (*policy).cur } {
unsafe { __cpufreq_driver_target(policy, (*policy).max, (1 | BIT!(2i32)) as u32) };
} else {
if (unsafe { (*policy).min }) > unsafe { (*policy).cur } {
unsafe { __cpufreq_driver_target(policy, (*policy).min, (0 | BIT!(2i32)) as u32) };
}
}
}

