// Single value that denotes runtime == period, ie unlimited time.
fn normal_policy(policy: i32) -> i32 {
(policy == 0) as i32
}

fn fair_policy(policy: i32) -> i32 {
(normal_policy(policy) != 0 || policy == 3) as i32
}

fn dl_policy(policy: i32) -> i32 {
(policy == 6) as i32
}

fn task_has_dl_policy(p: *mut task_struct) -> i32 {
dl_policy((unsafe { (*p).policy }) as i32)
}

